patch_result.patch:
--- a/gpac/src/isomedia/box_code_base.c
+++ b/gpac/src/isomedia/box_code_base.c
@@ -4286,7 +4286,16 @@
 		if (GF_4CC((u32)data[i+4], (u8)data[i+5], (u8)data[i+6], (u8)data[i+7]) == GF_ISOM_BOX_TYPE_ESDS) {
 			GF_BitStream *mybs = gf_bs_new(data + i, size - i, GF_BITSTREAM_READ);
 			gf_bs_set_cookie(mybs, GF_ISOM_BS_COOKIE_NO_LOGS);
-			if (ptr->esd) gf_isom_box_del_parent(&ptr->child_boxes, (GF_Box *)ptr->esd);
+			if (ptr->esd) {
+				GF_Box *old_esd = (GF_Box *) ptr->esd;
+				/* remove all ownership references before deleting the old box */
+				ptr->esd = NULL;
+				gf_isom_box_remove_from_parent(s, old_esd);
+				if (s->child_boxes) {
+					gf_list_del_item(s->child_boxes, old_esd);
+				}
+				gf_isom_box_del(old_esd);
+			}
 			ptr->esd = NULL;
 			e = gf_isom_box_parse((GF_Box **)&ptr->esd, mybs);
 			gf_bs_del(mybs);

args:
@@ -4286,8 +4286,15 @@
 		if (GF_4CC((u32)data[i+4], (u8)data[i+5], (u8)data[i+6], (u8)data[i+7]) == GF_ISOM_BOX_TYPE_ESDS) {
 			GF_BitStream *mybs = gf_bs_new(data + i, size - i, GF_BITSTREAM_READ);
 			gf_bs_set_cookie(mybs, GF_ISOM_BS_COOKIE_NO_LOGS);
-			if (ptr->esd) gf_isom_box_del_parent(&ptr->child_boxes, (GF_Box *)ptr->esd);
+			if (ptr->esd) {
+				GF_Box *old_esd = (GF_Box *) ptr->esd;
+				/* remove all ownership references before deleting the old box */
+				ptr->esd = NULL;
+				gf_isom_box_remove_from_parent(s, old_esd);
+				if (s->child_boxes) {
+					gf_list_del_item(s->child_boxes, old_esd);
+				}
+				gf_isom_box_del(old_esd);
+			}
 			ptr->esd = NULL;
 			e = gf_isom_box_parse((GF_Box **)&ptr->esd, mybs);
 			gf_bs_del(mybs);
